import type { SearchInputConfig, ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { companyService } from '../../services/company/companyService';
import { createStaticLookupSearchConfig } from './createStaticLookupSearchConfig';

export type CompanySearchLabelOpts = {
  codeHeaderLabel?: string;
  nameHeaderLabel?: string;
};

/** Chi nhánh / cửa hàng — `companyService.getActiveList()`, filter client. */
export function createCompanySearchConfig(
  labels: CompanySearchLabelOpts = {},
): SearchInputConfig<ActiveCompanyItem> {
  return createStaticLookupSearchConfig({
    loadItems: () => companyService.getActiveList(),
    getKey: item => item.code ?? item.id,
    getCode: item => item.code ?? item.id,
    getName: item => item.name,
    getFilterText: item => `${item.code ?? item.id} ${item.name} ${item.shortName ?? ''}`,
    getSingleDisplay: item => `${item.code ?? item.id} — ${item.name}`,
    codeHeaderLabel: labels.codeHeaderLabel ?? 'Mã CN',
    nameHeaderLabel: labels.nameHeaderLabel ?? 'Tên chi nhánh',
  });
}

/** Cửa hàng trên phiếu KH — cùng nguồn company, nhãn CH. */
export function createStoreSearchConfig(): SearchInputConfig<ActiveCompanyItem> {
  return createCompanySearchConfig({
    codeHeaderLabel: 'Mã CH',
    nameHeaderLabel: 'Tên cửa hàng',
  });
}
