import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import { createStaticLookupSearchConfig } from './createStaticLookupSearchConfig';

/** Lookup item = Master `ExpenseItem` (`/dm/chi-phi`) — không dùng FPC `/fpc/cost-codes` seed. */
export interface ExpenseItemLookupItem {
  id: string;
  code: string;
  name: string;
  accountCode?: string;
  isActive?: boolean;
}

interface ExpenseItemApiRow {
  id: string;
  code: string;
  name: string;
  accountCode?: string | null;
  isActive?: boolean;
}

interface PagedExpenseItems {
  items?: ExpenseItemApiRow[];
}

/**
 * Load Danh mục chi phí (Master shared catalog).
 * Parity Finance `createClassifyLookupConfigs` — `GET /master/expense-items`.
 */
export async function fetchExpenseItems(): Promise<ExpenseItemLookupItem[]> {
  const res = await apiClient.get<BffResponse<PagedExpenseItems | ExpenseItemApiRow[]>>(
    '/master/expense-items?page=1&pageSize=500',
  );
  const data = unwrap(res);
  const list = Array.isArray(data) ? data : (data?.items ?? []);
  return list
    .filter(c => c.isActive !== false)
    .map(c => ({
      id: String(c.id),
      code: c.code,
      name: c.name,
      accountCode: (c.accountCode || '').trim() || undefined,
      isActive: c.isActive,
    }));
}

/**
 * Mã CP trên phiếu KH — SSOT = Danh mục chi phí (`expense-items`).
 * Cấm hard seed / FPC CostCode EnsureDefaults.
 */
export function createExpenseItemSearchConfig(
  preloaded?: ExpenseItemLookupItem[],
): SearchInputConfig<ExpenseItemLookupItem> {
  return createStaticLookupSearchConfig({
    loadItems: async () => {
      if (Array.isArray(preloaded) && preloaded.length > 0) return preloaded;
      return fetchExpenseItems();
    },
    getKey: item => item.code,
    getCode: item => item.code,
    getName: item => item.name,
    getFilterText: item => `${item.code} ${item.name} ${item.accountCode ?? ''}`,
    getSingleDisplay: item => `${item.code} — ${item.name}`,
    codeHeaderLabel: 'Mã CP',
    nameHeaderLabel: 'Tên khoản mục',
    noCache: true,
  });
}

/** @deprecated Dùng `createExpenseItemSearchConfig` — alias tương thích tạm. */
export function createCostCodeSearchConfig(
  _tab?: 'revenue' | 'expense' | 'all',
  preloaded?: ExpenseItemLookupItem[],
): SearchInputConfig<ExpenseItemLookupItem> {
  return createExpenseItemSearchConfig(preloaded);
}
